insert into public.product_catalog (id, name, brand, category, product_type, summary, price, image, url, tags, health_functions, where_to_buy, where_to_buy_in_stock, safety, doctor_opinion, community_review, effectiveness, clinician_opinion_source, clinician_attribution, source, internal, requires_prescription, user_rating, is_active, extra)
values
  ('p-najeau-follicle-drops', 'Najeau Follicle Drops Pre-Shampoo Scalp Oil', 'Najeau', 'hair', 'physical', 'A pre-shampoo scalp oil in a glass dropper bottle, made from cold-pressed olive, castor, soybean, basil and neem seed oils with aloe. You apply it to a dry scalp, leave it on for several minutes, then shampoo it out, 1 to 3 times a week. Najeau says it breaks down oil and product buildup and leaves the scalp hydrated and pH balanced, and also that it increases blood flow to the follicle and stimulates hair growth.', '$49.00 for 1.7 fl oz on Amazon', 'https://m.media-amazon.com/images/I/512842JgyVL._AC_SL500_.jpg', 'https://www.amazon.com/dp/B0FM1JK11M', '["najeau","follicle drops","hair","scalp","scalp oil","pre-shampoo","dry scalp","buildup","olive oil","cosmetic"]'::jsonb, '["skin-hair"]'::jsonb, '["Amazon"]'::jsonb, '{}'::jsonb, '{"fdaStatus":"Sold as a cosmetic; not an FDA-approved drug for hair loss.","materials":"Plant-oil blend in a glass dropper bottle, rinsed out with shampoo. Amazon''s title calls it fragrance-free, but the ingredient list ends with linalool, geraniol, eugenol, citral and limonene, which are fragrance allergens (likely from the basil oil). It also contains soybean oil.","recalls":"No recalls found.","sideEffects":"Per Najeau''s Amazon safety information: for external use only, avoid the eyes, patch test before use, and ask a physician first if pregnant, nursing or under medical treatment.","opinionAlerts":"Najeau''s Amazon listing says it is \"consumer tested for visible results in 4 weeks\" but gives no numbers or study details. Its growth claims (more blood flow to the follicle, stimulates growth) have no study behind them that ayna could find."}'::jsonb, 'Najeau says Follicle Drops break down product and oil buildup at the root, leave the scalp pH balanced and hydrated, increase blood flow to the hair bulb and follicle, and stimulate hair growth. It says consumer testing showed a less dry, itchy and oily scalp in 4 weeks, but gives no numbers, sample size or method. No study of this product was found.

This is a rinse-off oil used 1 to 3 times a week, so it is best thought of as a scalp-conditioning and cleansing step. ayna did not find research it could read showing that the oils in it (olive, castor, soybean, basil, neem) grow hair or reduce hair loss in people, so the growth claims are the brand''s. The rosemary oil named on Amazon is not in the published ingredient list.

The ingredient list also contains linalool, geraniol, eugenol, citral and limonene, which are common fragrance allergens, even though the product is sold as fragrance-free. If you have a fragrance or soy allergy, check with a dermatologist first.

If you have thinning hair, a dermatologist can check for causes and discuss treatments with stronger evidence. Minoxidil is the over-the-counter hair-loss treatment the FDA has approved for women.', 'On Amazon it has 4.5 out of 5 stars from 25 ratings; 57% are five stars and none are one or two stars. All of the reviews shown on the page are Amazon Vine reviews of a free product. Reviewers mostly describe a less dry scalp and an oil that rinses clean, and several say the herbal smell is strong. No reviews were found on a Najeau brand site.', 'A cleansing and conditioning scalp oil. No study of this product was found, and ayna found no human evidence it could read that its oils grow hair.', 'brand', 'Product claims are sourced from Najeau; no independent clinician endorsement verified by ayna.', 'curated', false, false, null, true, '{"ingredients":"Full ingredient list per Najeau''s SalonCentric listing: Olea Europaea (Olive) Fruit Oil, Ricinus Communis (Castor) Seed Oil, Glycine Soja (Soybean) Oil, Ocimum Basilicum (Basil) Oil, Aloe Barbadensis Leaf Juice, Azadirachta Indica Seed Oil, Tocopherol, Linalool, Geraniol, Eugenol, Citral, Limonene. The Amazon listing names rosemary oil as a key ingredient, but rosemary is not in this list.","doctorOpinionShort":"A rinse-off pre-shampoo oil for dry scalp and buildup. Its hair-growth claims have no study behind them that ayna could find, the rosemary named on Amazon isn''t in the ingredient list, and it contains fragrance allergens despite a fragrance-free label.","doctorOpinionCitations":[{"url":"https://www.amazon.com/dp/B0FM1JK11M","label":"Amazon: Najeau Follicle Drops, claims, directions and safety information"},{"url":"https://www.saloncentric.com/6039-NAJ1003.html","label":"SalonCentric: Najeau Follicle Drops, full ingredient list"},{"url":"https://www.accessdata.fda.gov/scripts/cder/daf/index.cfm?event=overview.process&ApplNo=021812","label":"FDA (Drugs@FDA): NDA 021812, Women''s Rogaine 5% minoxidil foam, over-the-counter","chipLabel":"FDA: minoxidil for women"}],"whoItsFor":["People with a dry scalp or product buildup who like a pre-wash scalp oil routine","Not a hair-loss treatment: for thinning hair, see a dermatologist about options with evidence","Not a good fit if you''re allergic to soy or to common fragrance allergens such as linalool or limonene"],"howToUse":{"intro":"Per Najeau: use 1 to 3 times a week, or as needed, before shampooing.","steps":["Shake well.","Part dry hair into sections and apply 3 to 6 drops in each section.","Massage gently into the scalp with your fingers or a scalp massager.","Leave on for several minutes, then double shampoo and condition as usual."],"sourceUrl":"https://www.amazon.com/dp/B0FM1JK11M","sourceLabel":"Amazon: Najeau Follicle Drops"},"warnings":["External use only. Avoid the eyes; if contact occurs, rinse thoroughly with water (per Najeau).","Patch test before use (per Najeau). Contains soybean oil and the fragrance allergens linalool, geraniol, eugenol, citral and limonene.","Pregnant, nursing or under medical treatment: consult a physician before use (per Najeau).","Keep out of reach of children."],"ingredientScience":[],"scientificCitations":[{"url":"https://www.aad.org/public/diseases/hair-loss/types/female-pattern","text":"American Academy of Dermatology: Female pattern hair loss","summary":"The AAD says the FDA has approved 2% and 5% minoxidil as a non-prescription treatment for female pattern hair loss and calls it the most-recommended treatment. This is general guidance, not product-specific validation."}],"verificationLinks":{"doctor":{"links":[]},"scientific":{"links":[]},"community":{"links":[{"platform":"amazon","url":"https://www.amazon.com/dp/B0FM1JK11M","text":"Amazon: Najeau Follicle Drops reviews","summary":"4.5 out of 5 stars from 25 ratings as of October 2026; the reviews shown are Vine reviews of a free product."}]}},"integrations":[],"badges":[],"isEmergingBrand":true}'::jsonb)
